<?php require_once __DIR__.'/includes/bootstrap.php';require_role(['admin']);$rows=$conn->query('SELECT l.*,u.full_name,u.email FROM activity_logs l LEFT JOIN users u ON u.id=l.user_id ORDER BY l.id DESC LIMIT 300');page_header('Activity logs');?><div class="page-heading"><div><p class="eyebrow">AUDIT TRAIL</p><h1>Activity logs</h1><p class="muted">Latest 300 actions for accountability and troubleshooting.</p></div></div><div class="table-wrap panel"><table><thead><tr><th>Time</th><th>User</th><th>Action</th><th>Details</th><th>IP</th></tr></thead><tbody><?php while($r=$rows->fetch_assoc()):?><tr><td><?=e($r['created_at'])?></td><td><?=e($r['full_name']??'Deleted user')?><div class="muted small"><?=e($r['email']??'')?></div></td><td><?=e($r['action'])?></td><td><?=e($r['details'])?></td><td><?=e($r['ip_address'])?></td></tr><?php endwhile;?></tbody></table></div><?php page_footer();?>